<div class="d-flex justify-content-between mb-3"><div><h4 class="mb-0">Extra barcodes &amp; packs</h4><div class="text-muted"><?= e($p['sku'] . ' - ' . $p['name']) ?> &middot; main barcode <b><?= e($p['barcode']) ?></b></div></div><a class="btn btn-outline-secondary align-self-start" href="javascript:history.back()">Back</a></div>
<div class="alert alert-info">Use this page when the same product has more than one barcode. Give a <b>carton / multipack</b> barcode "Units per scan" greater than 1 (for example 24) and the POS adds that many units when it is scanned.</div>
<div class="card mb-3"><table class="table table-sm mb-0 align-middle"><thead class="table-light"><tr><th>Barcode</th><th>Label</th><th class="text-end">Units per scan</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['barcode']) ?></td><td><?= e($r['label']) ?></td><td class="text-end"><?= fq($r['qty_per_scan']) ?></td><td class="text-end"><?php if (Auth::can('inventory.products.edit')): ?><form method="post" class="d-inline" data-confirm="Remove this barcode?"><?= csrf_field() ?><input type="hidden" name="do" value="remove"><input type="hidden" name="bid" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="4" class="text-center text-muted py-3">No extra barcodes.</td></tr><?php endif; ?></tbody></table></div>
<?php if (Auth::can('inventory.products.edit')): ?><form method="post" class="card card-body row g-2 flex-row needs-validation" novalidate><?= csrf_field() ?><input type="hidden" name="do" value="add">
<div class="col-md-4"><input name="barcode" class="form-control" placeholder="Barcode" required maxlength="40"></div><div class="col-md-3"><input name="label" class="form-control" placeholder="Label (e.g. Carton of 24)" maxlength="60"></div>
<div class="col-md-3"><input name="qty_per_scan" type="number" step="any" min="0.001" value="1" class="form-control" title="Units added per scan"></div><div class="col-md-2"><button class="btn btn-primary w-100 once">Add</button></div></form><?php endif; ?>
